<div class="page-heading"><div><div class="eyebrow">Pelimpahan</div><h1><?= $technician?'Perusahaan yang saya wakili':'Pelaku usaha perusahaan' ?></h1><p>Hubungan baru memerlukan persetujuan kedua pihak, lalu verifikasi dinas. Akses data perusahaan baru aktif setelah semuanya selesai.</p></div></div>
<?php if ($this->metro->can($current_user->id,'self.delegation.invite')): ?><section class="card form-card"><h2><?= $technician?'Ajukan hubungan dengan perusahaan':'Tunjuk pelaku usaha terverifikasi' ?></h2><?php if (!$technician && !$eligible_company): ?><div class="alert danger">Pilih jenis profil instansi/perusahaan dan isi nama perusahaan pada <a href="<?= site_url('profil') ?>">profil</a> untuk mengelola pelimpahan.</div><?php elseif ($technician && ($current_user->phone_verification_required && !$current_user->phone_verified_at || !$technician_profile || $technician_profile->verification_status!=='approved')): ?><div class="alert danger">Verifikasi nomor telepon dan persetujuan dinas diperlukan sebelum mengajukan hubungan perusahaan.</div><?php else: ?><form method="post" action="<?= site_url('pelimpahan/undang') ?>"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><label>Cari <?= $technician?'perusahaan':'pelaku usaha' ?><input type="search" id="counterpart-search" autocomplete="off" data-url="<?= site_url('pelimpahan/cari') ?>" placeholder="Ketik minimal dua huruf nama / username" required></label><input type="hidden" name="target_user_id" id="counterpart-id" required><div id="counterpart-results" class="counterpart-results" role="listbox" hidden></div><div id="counterpart-preview" class="counterpart-preview" hidden></div><button class="button primary" type="submit"><?= $technician?'Ajukan hubungan':'Kirim pelimpahan' ?></button></form><?php endif; ?></section><?php endif; ?>
<section class="section"><h2>Daftar hubungan</h2><div class="registry-list"><?php if ($rows): foreach ($rows as $row): $counterpart=(int)$row->initiated_by_user_id!==(int)$current_user->id; ?><article class="registry-item"><div class="section-heading compact"><div><strong><?= e($technician?($row->organization_name ?: $row->counterpart_name):$row->counterpart_name) ?></strong><small><?= e($row->counterpart_email) ?></small><small>Dimulai <?= e(tanggal_id($row->created_at,TRUE)) ?><?= $row->review_note?' · Catatan dinas: '.e($row->review_note):'' ?></small></div><span class="badge <?= $row->status==='active'?'success':($row->status==='pending_office'?'info':'danger') ?>"><?= e(array('awaiting_counterpart'=>'Menunggu pihak lain','pending_office'=>'Menunggu dinas','active'=>'Aktif','rejected'=>'Ditolak','revoked'=>'Dicabut')[$row->status] ?? $row->status) ?></span></div><div class="registry-actions"><?php if ($this->metro->can($current_user->id,'self.delegation.respond') && $row->status==='awaiting_counterpart' && $counterpart): ?><form method="post" action="<?= site_url('pelimpahan/tanggapi/'.$row->id) ?>"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><input type="hidden" name="action" value="accept"><button type="submit" class="button primary small-button">Setujui</button></form><?php endif; ?><?php if ($this->metro->can($current_user->id,'self.delegation.respond') && in_array($row->status,array('awaiting_counterpart','pending_office'),TRUE)): ?><form method="post" action="<?= site_url('pelimpahan/tanggapi/'.$row->id) ?>" onsubmit="return confirm('Tolak permintaan hubungan ini?')"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><input type="hidden" name="action" value="reject"><button type="submit" class="button outline small-button">Tolak</button></form><?php elseif ($this->metro->can($current_user->id,'self.delegation.respond') && $row->status==='active'): ?><form method="post" action="<?= site_url('pelimpahan/tanggapi/'.$row->id) ?>" onsubmit="return confirm('Cabut hubungan dan hentikan akses pelaku usaha ke data perusahaan?')"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><input type="hidden" name="action" value="revoke"><button type="submit" class="button outline small-button">Cabut akses</button></form><?php endif; ?></div></article><?php endforeach; else: ?><div class="card empty"><h3>Belum ada hubungan</h3><p>Gunakan email akun yang sudah terdaftar untuk mengajukan pelimpahan.</p></div><?php endif; ?></div></section>

